-- Generated by tools/food-data (npm run build -w @calorie/food-data); do not edit. The sources
-- are tools/food-data/sources; the review table is tools/food-data/generated/review.md.
-- 118 foods (92 USDA, 24 recipe, 2 label), 322 aliases.

on conflict (id) do update set
  name_tr = excluded.name_tr,
  category = excluded.category,
  kcal_per_100g = excluded.kcal_per_100g,
  protein_per_100g = excluded.protein_per_100g,
  carbs_per_100g = excluded.carbs_per_100g,
  fat_per_100g = excluded.fat_per_100g,
  typical_portion_g = excluded.typical_portion_g,
  unit_weights = excluded.unit_weights,
  source_kind = excluded.source_kind,
  source_ref = excluded.source_ref,
  searchable = excluded.searchable;

-- Foods no longer in the sources stay for the meals that use them but leave search (FR-010).
update public.foods set searchable = false where id <> all (array['almonds', 'apple', 'avocado', 'ayran', 'baklava', 'banana', 'beef_mince_lean_raw', 'beef_mince_raw', 'beef_patty', 'beef_raw', 'beef_sirloin_raw', 'berries', 'bolognese', 'borek', 'bread_crumbs', 'broccoli', 'brown_rice', 'brown_rice_cooked', 'bulgur', 'bulgur_dry', 'bun', 'butter', 'cacik', 'carrot', 'chicken_boiled', 'chicken_breast_grilled', 'chicken_breast_raw', 'chicken_roast', 'chicken_saute', 'chicken_thigh', 'chicken_thigh_raw', 'chicken_wing', 'chickpeas', 'chickpeas_boiled', 'coban_salata', 'corn', 'corn_boiled', 'cornstarch', 'cucumber', 'doner', 'egg', 'egg_boiled', 'egg_fried', 'eggplant', 'flour', 'fried_chicken', 'fries', 'garlic', 'green_beans', 'green_pepper', 'greens', 'honey', 'hummus', 'iskender', 'karniyarik', 'kasar_cheese', 'kofte', 'kuru_fasulye', 'lahmacun', 'lentil_soup', 'lentils', 'lentils_dry', 'manti', 'menemen', 'milk', 'molasses', 'noodles', 'noodles_cooked', 'oats', 'oats_dry', 'oil', 'olives', 'onion', 'orange', 'pasta_dry', 'phyllo', 'pide', 'pizza', 'potato', 'potato_raw', 'protein_powder', 'red_pepper', 'rice_raw', 'salmon', 'salmon_cooked', 'salt', 'sesame', 'shrimp', 'shrimp_cooked', 'simit', 'spaghetti', 'steak', 'stir_fry_veg', 'strawberries', 'sucuk', 'sugar', 'sunflower_oil', 'sutlac', 'sweet_potato', 'sweet_potato_baked', 'tangerine', 'toast_bread', 'tomato', 'tomato_paste', 'tost', 'tuna', 'tuna_oil', 'turkey', 'walnuts', 'white_beans_dry', 'white_bread', 'white_cheese', 'white_rice', 'whole_wheat_bread', 'yeast', 'yogurt', 'yogurt_greek', 'zucchini']);

-- Every food is curated in part A, so the release owns all aliases.
delete from public.food_aliases;
